package framework;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.file.*;
import java.util.Map;

public final class CommonMethods {
  private static final ObjectMapper JSON = new ObjectMapper();
  private CommonMethods() {}
  public static Map<String, Object> run() { return read(Path.of("config/run.config.json")); }
  public static String environment() {
    String value = System.getProperty("env", System.getenv().getOrDefault("TEST_ENV", String.valueOf(run().get("environment"))));
    if (!Files.isRegularFile(Path.of("test-data", value + ".json"))) throw new IllegalArgumentException("Unknown environment or missing test data: " + value);
    return value;
  }
  public static Map<String, Object> testData() { return read(Path.of("test-data", environment() + ".json")); }
  public static void step(String message) { System.out.println("[STEP] " + message); }
  public static void error(String test, Throwable error) {
    try { Files.createDirectories(Path.of("reports")); Files.writeString(Path.of("reports/errors.log"), "[FAIL] " + test + "\n" + error + "\n", StandardOpenOption.CREATE, StandardOpenOption.APPEND); }
    catch (IOException ignored) { System.err.println("[ERROR] Could not write reports/errors.log"); }
  }
  private static Map<String, Object> read(Path path) {
    try { return JSON.readValue(path.toFile(), new TypeReference<>() {}); }
    catch (IOException error) { throw new IllegalStateException("Cannot read " + path, error); }
  }
}
